6:   setDescription(agentKey: string, description: string): void;
7:   deleteDescription(agentKey: string): void;
8: }
9: 
10: /**
11:  * Stores human-authored descriptions for Agent-generated entities.
12:  *
13:  * The generated manifest may be replaced wholesale. Keeping manual prose in
14:  * graph.sqlite makes it durable and lets the extension reapply it by stable
15:  * Agent key after every generation.
16:  */
17: export class AgentEntityOverrideService
18:   implements AgentEntityDescriptionOverrideStore
19: {
20:   constructor(private readonly dbService: DatabaseService) {}
21: 
22:   public getDescription(agentKey: string): string | undefined {
23:     const exactDescription = this.getExactDescription(agentKey);
24:     if (exactDescription !== undefined) {
25:       return exactDescription;
26:     }
27:     return this.findIdentityOverride(agentKey)?.description;
28:   }
29: 
30:   private getExactDescription(agentKey: string): string | undefined {
31:     const db = this.dbService.getDatabase();
32:     const stmt = db.prepare(
33:       'SELECT description FROM agent_entity_overrides WHERE agent_key = ?'
34:     );
35:     stmt.bind([agentKey]);
36: 
37:     if (!stmt.step()) {
38:       stmt.free();
39:       return undefined;
40:     }
41: 
42:     const row = stmt.getAsObject();
43:     stmt.free();
44:     return String(row.description);
45:   }
46: 
47:   public setDescription(agentKey: string, description: string): void {
48:     const db = this.dbService.getDatabase();
49:     const stmt = db.prepare(`
50:       INSERT INTO agent_entity_overrides (agent_key, description, updated_at)
51:       VALUES (?, ?, ?)
52:       ON CONFLICT(agent_key) DO UPDATE SET
53:         description = excluded.description,
54:         updated_at = excluded.updated_at
55:     `);
56:     stmt.run([agentKey, description, Date.now()]);
57:     stmt.free();
58:     this.dbService.save();
59:   }
60: 
61:   public deleteDescription(agentKey: string): void {
62:     const db = this.dbService.getDatabase();
63:     const storedKey =
64:       this.getExactDescription(agentKey) !== undefined
65:         ? agentKey
66:         : this.findIdentityOverride(agentKey)?.agentKey;
67:     if (storedKey === undefined) {
68:       return;
69:     }
70:     const stmt = db.prepare(
71:       'DELETE FROM agent_entity_overrides WHERE agent_key = ?'
72:     );
73:     stmt.run([storedKey]);
74:     stmt.free();
75:     this.dbService.save();
76:   }
77: 
78:   private findIdentityOverride(
79:     agentKey: string
80:   ): { agentKey: string; description: string } | undefined {
81:     const identityKey = normalizeEntityIdentity(agentKey);
82:     const db = this.dbService.getDatabase();
83:     const stmt = db.prepare(
84:       'SELECT agent_key, description FROM agent_entity_overrides'
85:     );
86:     const matches: Array<{ agentKey: string; description: string }> = [];
87:     while (stmt.step()) {
88:       const row = stmt.getAsObject();
89:       const storedKey = String(row.agent_key);
90:       if (normalizeEntityIdentity(storedKey) === identityKey) {
91:         matches.push({
92:           agentKey: storedKey,
93:           description: String(row.description),
94:         });
95:       }
96:     }
97:     stmt.free();
98:     return matches.length === 1 ? matches[0] : undefined;
99:   }
100: }
